"""Owner 2026-11-24: 敵の召喚獣がウゴカザルなら卵を使わず白兵で倒す。

ウゴカザルの2つの技「なぐれっ！」「かむしれ！」（かきむしれ！）はどちらも
0ダメージ (hanjuku_reference.MONSTER_SKILLS)。ゾンビと同じく将軍を脅かさない
ため、たまご・おくのてを消費せず「こうげき」だけで処理する。実画面の敵召喚獣が
1体だけ読め、名前が完全一致したときだけ適用する。
"""
from pathlib import Path

from docich.hanjuku_speedrun import hanjuku_policy as policy
from docich.hanjuku_speedrun.hanjuku_pixels import read_png
from docich.hanjuku_speedrun.hanjuku_screen import EggRow, parse

FRAME = Path(__file__).parent.parent / 'fixtures/hanjuku/g684-artemis-dark-elf.png'


def encounter():
    screen = parse(read_png(FRAME))
    assert screen.kind == 'egg_battle_menu'
    mem = {'chapter': 1, 'egg_uses': {'アルテミス': 4}, 'battle': {
        'ally': 'アルテミス', 'enemy': 'ブラウニー', 'ally_hp': 49, 'enemy_hp': 33,
        'start_ally_hp': 49, 'start_enemy_hp': 33, 'side': 'attack',
        'planned_cards': [], 'cards_used': [], 'card_evidence_version': 1}}
    return screen, mem


def with_ugokazaru(screen, hp=100):
    screen.egg_rows[1] = EggRow('ウゴカザル', hp, 'enemy', 80)
    return screen


def egg_decision(mem):
    return next(d for d in mem['_records'] if d['decision'] == 'egg_battle')


def test_ugokazaru_is_answered_by_melee_without_our_egg():
    screen, mem = encounter()
    with_ugokazaru(screen)
    assert policy.egg_battle_step(screen, mem) == [policy.pad('a')]
    assert mem['egg_action'] == 'attack'
    assert mem['egg_needed'] is False
    decision = egg_decision(mem)
    assert decision['observed_metric']['egg_need']['rule'] == 'melee_only_summon'
    assert decision['observed_metric']['egg_need']['enemy_monster'] == 'ウゴカザル'
    assert decision['strategy_variant'] == 'egg_battle_attack'
    assert 'ウゴカザル' in decision['reason']
    assert mem['battle']['melee_only_summon'] is True


def test_ugokazaru_overrides_a_huge_monster_hp():
    screen, mem = encounter()
    with_ugokazaru(screen, hp=900)
    policy.egg_battle_step(screen, mem)
    assert mem['egg_action'] == 'attack'
    assert egg_decision(mem)['observed_metric']['egg_need']['rule'] == 'melee_only_summon'


def test_ugokazaru_skips_the_okunote_lottery():
    mem = {'chapter': 1}
    battle = {'side': 'defense', 'castle': 'ゴーメン', 'ally': 'アルテミス',
              'enemy': 'ブラウニー', 'egg_battle': True, 'summon_egg_unavailable': True,
              'card_summon_observed': True, 'okunote_only_observed': True,
              'summon_enemy_hp': 200, 'ally_hp': 60}
    assert policy._defender_summon_preempt(mem, battle)['due'] is True
    battle['melee_only_summon'] = True
    assert policy._defender_summon_preempt(mem, battle) is None


def test_narration_names_ugokazaru():
    from docich.hanjuku_speedrun import hanjuku_commentary as commentary
    record = {'decision': 'egg_battle', 'strategy_variant': 'egg_battle_attack',
              'observed_metric': {'egg_need': {'rule': 'melee_only_summon',
                                               'enemy_monster': 'ウゴカザル'}}}
    assert commentary.compose(record)[1] == '敵の召喚獣はウゴカザルなので、たまごを使わず白兵で対処します。'
